import{_ as s,C as r,c as o,o as i,a3 as a,G as n}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Maintenance teams","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/maintenance/setup/maintenance-teams.md","filePath":"master/supply-chain/maintenance/setup/maintenance-teams.md","lastUpdated":1793074831000}'),l={name:"master/supply-chain/maintenance/setup/maintenance-teams.md"};function m(c,e,h,d,u,p){const t=r("ImagePopup");return i(),o("div",null,[e[0]||(e[0]=a('<h1 id="maintenance-teams" tabindex="-1">Maintenance teams <a class="header-anchor" href="#maintenance-teams" aria-label="Permalink to &quot;Maintenance teams&quot;">​</a></h1><p>A maintenance team is a named group of people who repair or service equipment. You give each piece of equipment a team, and each request a team. This tells everyone who owns the job, and it lets you group work by team.</p><blockquote><p><strong>In simple words:</strong> A team is the crew that takes care of a set of machines.</p></blockquote><p>Open <code>Maintenance → Configurations → Teams</code>.</p><div class="info custom-block"><p class="custom-block-title">Prerequisite</p><p>Team members are users. Create them first in <a href="./../../../general-settings/users/manage-users.html">Manage users</a>. The team <strong>Internal Maintenance</strong> already exists, so you can start without creating one.</p></div><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The page lists every team. Two tabs sit above the list.</p><ul><li><strong>All:</strong> teams in use.</li><li><strong>Archived:</strong> teams you deleted. You can restore them from here.</li></ul><p>Columns are <strong>Name</strong>, <strong>Company</strong> and <strong>Team Members</strong>. Members appear as small badges. Each row has <strong>Edit</strong> and <strong>Delete</strong> actions.</p>',9)),n(t,{src:"/images1/maintenance/set_teams_list.png",alt:"Maintenance Teams list with the All and Archived tabs, showing Internal Maintenance and Electrical Maintenance Team"}),e[1]||(e[1]=a('<h2 id="create-a-team" tabindex="-1">Create a team <a class="header-anchor" href="#create-a-team" aria-label="Permalink to &quot;Create a team&quot;">​</a></h2><p>This example makes the <strong>Electrical Maintenance Team</strong>, with Linda Ndlovu as the member.</p><ol><li>Open <code>Maintenance → Configurations → Teams</code>.</li><li>Click <strong>New Team</strong>. A window opens.</li><li>Fill in the form.</li></ol><ul><li><strong><em>Name:</em></strong> Required. Use a name people recognise, such as <code>Electrical Maintenance Team</code>.</li><li><strong><em>Team Members:</em></strong> Pick one or more users. Choose <strong>Linda Ndlovu</strong>.</li><li><strong><em>Company:</em></strong> Fills with your company. Change it only if you run several companies.</li></ul>',4)),n(t,{src:"/images1/maintenance/set_team_form.png",alt:"Create Maintenance Team window filled with Electrical Maintenance Team and member Linda Ndlovu"}),e[2]||(e[2]=a('<ol start="4"><li>Click <strong>Create</strong>. The window closes and the team appears in the list.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Click <strong>Create &amp; create another</strong> to add several teams in a row.</p></div><h2 id="edit-or-delete-a-team" tabindex="-1">Edit or delete a team <a class="header-anchor" href="#edit-or-delete-a-team" aria-label="Permalink to &quot;Edit or delete a team&quot;">​</a></h2><p>Click <strong>Edit</strong> on a row to change the name, members or company. Click <strong>Delete</strong> to archive the team. It moves to the <strong>Archived</strong> tab. Use <strong>Restore selected</strong> there to bring it back. <strong>Force delete selected</strong> removes it for good.</p><h2 id="where-teams-are-used" tabindex="-1">Where teams are used <a class="header-anchor" href="#where-teams-are-used" aria-label="Permalink to &quot;Where teams are used&quot;">​</a></h2><ul><li>On <strong>Equipment</strong>, the <strong>Maintenance Team</strong> field says who looks after the machine.</li><li>On a request, <strong>Team</strong> is required. It fills from the equipment you pick.</li><li>Teams and equipment share a company. If you change the company on a record, the team clears and you pick again.</li></ul><h2 id="behind-the-scenes" tabindex="-1">Behind the scenes <a class="header-anchor" href="#behind-the-scenes" aria-label="Permalink to &quot;Behind the scenes&quot;">​</a></h2><p>When you create a request without equipment, Aureus uses the first team of the company. For a new installation, this is <strong>Internal Maintenance</strong>.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./equipment-categories.html">Equipment categories</a></li><li><a href="./../equipment/add-equipment.html">Add equipment</a></li><li><a href="./../requests/create-request.html">Create a maintenance request</a></li></ul>',10))])}const T=s(l,[["render",m]]);export{_ as __pageData,T as default};
